cd /workspace
PYTHONPATH=/workspace/vendor python3 - <<'PY'
import numpy as np, warnings
warnings.filterwarnings('ignore')
from scipy.optimize import curve_fit
def conv(s): return float(s.replace(b',',b'.') if isinstance(s,bytes) else s.replace(',','.'))
raw=np.loadtxt('graphene.dat',delimiter='\t',converters={0:conv,1:conv})
x,y=raw[:,0],raw[:,1]
s=1e7/x
o=np.argsort(s); s,y=s[o],y[o]

def lor_const(u,off,A,u0,g): return off + A*g**2/((u-u0)**2+g**2)
def lor_lin(u,off,sl,A,u0,g): return off + sl*(u-u0) + A*g**2/((u-u0)**2+g**2)
def gau_const(u,off,A,u0,sig): return off + A*np.exp(-0.5*((u-u0)/sig)**2)
def gau_lin(u,off,sl,A,u0,sig): return off + sl*(u-u0) + A*np.exp(-0.5*((u-u0)/sig)**2)

def fit(u,yy,p0,model,extra):
    try:
        p,cov=curve_fit(model,u,yy,p0=p0,maxfev=200000)
        r=yy-model(u,*p); rms=np.sqrt(np.mean(r**2))
        perr=np.sqrt(np.diag(cov))
        return p,rms,perr
    except Exception as e:
        return None,None,str(e)

print("=== s-space (Raman shift) fits ===")
for name,u0g,wins in [('G',1580,[(1500,1680),(1530,1650),(1545,1630),(1550,1620)]),
                      ('2D',2670,[(2480,2900),(2540,2820),(2580,2760),(2600,2740)])]:
    print(f"\n--- {name} ---")
    for (lo,hi) in wins:
        m=(s>=lo)&(s<=hi); u,yy=s[m],y[m]
        # constant lorentz
        p,rms,perr=fit(u,yy,[np.median(yy[:10]),max(yy)-np.median(yy),u0g,10],lor_const,None)
        if p is not None:
            print(f" win[{lo},{hi}] n={len(u):3d} CONST-LOR off={p[0]:8.1f} A={p[1]:8.1f} x0={p[2]:8.2f} gam={p[3]:6.2f} FWHM={2*p[3]:6.2f} rms={rms:6.1f} | x0±{perr[2]:.2f} gam±{perr[3]:.2f}")
        p,rms,perr=fit(u,yy,[np.median(yy[:10]),0,max(yy)-np.median(yy),u0g,10],lor_lin,None)
        if p is not None:
            print(f" win[{lo},{hi}] n={len(u):3d} LIN-LOR   off={p[0]:8.1f} sl={p[1]:7.2f} A={p[2]:8.1f} x0={p[3]:8.2f} gam={p[4]:6.2f} FWHM={2*p[4]:6.2f} rms={rms:6.1f}")
PY
OUTER
